384	 * Looks in:
385	 * 1. Tasks created in this derive session (specToTaskMap)
386	 * 2. Existing tasks linked to the parent spec (alignmentIndex)
387	 *
388	 * Only returns tasks that are NOT in 'cancelled' state (AC-15).
389	 */
390	function getParentTaskRef(
391	  parentSpec: LoadedSpecItem,
392	  specToTaskMap: Map<string, LoadedTask>,
393	  alignmentIndex: AlignmentIndex,
394	  index: ReferenceIndex,
395	): string | undefined {
396	  // Check if we created a task for this parent in this session
397	  const sessionTask = specToTaskMap.get(parentSpec._ulid);
398	  if (sessionTask && sessionTask.status !== "cancelled") {
399	    return getTaskRef(sessionTask, index);
400	  }
401	
402	  // Check if an existing task is linked to this parent spec
403	  // AC: @cmd-derive ac-15 - skip cancelled tasks
404	  const linkedTasks = alignmentIndex.getTasksForSpec(parentSpec._ulid);
405	  const activeTask = linkedTasks.find((task) => task.status !== "cancelled");
406	  if (activeTask) {
407	    return getTaskRef(activeTask, index);
408	  }
409	
410	  return undefined;
411	}
