420	 * Uses tasks created in the current derive session first, then falls back to
421	 * existing non-cancelled tasks linked to the depended-on spec.
422	 */
423	function resolveSpecDependencyTaskRefs(
424	  specItem: LoadedSpecItem,
425	  specToTaskMap: Map<string, LoadedTask>,
426	  alignmentIndex: AlignmentIndex,
427	  index: ReferenceIndex,
428	): { taskRefs: string[]; warnings: string[] } {
429	  const taskRefs: string[] = [];
430	  const warnings: string[] = [];
431	
432	  for (const depRef of specItem.depends_on || []) {
433	    const resolved = index.resolve(depRef);
434	    if (!resolved.ok) {
435	      warnings.push(
436	        `Spec dependency ${depRef} for @${specItem.slugs[0] || specItem._ulid} could not be resolved; skipping task dependency link.`,
437	      );
438	      continue;
439	    }
440	
441	    const dependencyTask =
442	      specToTaskMap.get(resolved.ulid) ||
443	      alignmentIndex
444	        .getTasksForSpec(resolved.ulid)
445	        .find((task) => task.status !== "cancelled");
446	
447	    if (dependencyTask) {
448	      taskRefs.push(getTaskRef(dependencyTask, index));
449	      continue;
450	    }
451	
452	    warnings.push(
453	      `Spec dependency ${depRef} for @${specItem.slugs[0] || specItem._ulid} has no active derived task; created task without linking it.`,
454	    );
455	  }
456	
457	  return {
458	    taskRefs: Array.from(new Set(taskRefs)),
459	    warnings,
460	  };
461	}
